#!/usr/bin/env python3
"""HBM-FORM-SPLIT-8+REFORM-B11 glue: port-cut copies of the VMS glue submodules (crossing regs -> kit face flops).
    mk_pc.py SRC_DIR OUT.sv"""
import sys
from pathlib import Path
S = Path(sys.argv[1])
def ed(txt, pairs):
    for a, b in pairs:
        n = txt.count(a)
        assert n == 1, (n, a[:80])
        txt = txt.replace(a, b)
    return txt
HDR = """// HBM-FORM-SPLIT-8+REFORM-B11 (glue_d15r RE-FORM): PORT-CUT copies of the VMS glue submodules for the 3-piece split of
// hfd_hgi_vms_glue_nw_t.  GENERATED by results/die_hbm_1105/form_split/glue_b11/mk_pc.py from the rtl/hbm_accel/generic/vm/static
// sources.  On every port that crosses between split pieces the boundary register is removed (an input register becomes a
// wire, an output register becomes its combinational next value), so the two kit face flops of a crossing (+1 out, +1 in)
// take the place of the two registers it had (producer output reg + consumer input reg): 0 added cycles on every crossing.
// Only crossing ports change; die-facing ports keep their registers.  The cut regs only reset to the values their sources
// already hold in reset (valid state resets), so the unreset face flops flush within 2 reset edges (reset contract 64).
// DMUT (bench mutants): 1 rstop keeps the ri input reg (+1); 2 status takes the ring fault at the flags stage (+2);
// 3 hub keeps the cco input regs (+1); 4 rcl inverts the ri return port; 5 hub popcount drops source 9 (B13).
"""
out = [HDR]
# ---------------------------------------------------------------- ring stop
t = (S / "ot_vms_rstop_static.sv").read_text()
t = ed(t, [
 ("module ot_vms_rstop_static #(", "module ot_vms_rstop_static_pc #(\n    parameter integer DMUT=0,"),
 ("    reg [289:0] pi_q;\n", "    wire [289:0] pi_q=pi;                      // crossing input (hub): kit face flop\n"),
 ("    reg [265:0] ri_q;\n", "    reg [265:0] ri_r;\n    wire [265:0] ri_q=(DMUT==1)?ri_r:ri;       // crossing input (replay)\n    always @(posedge clk) ri_r<=ri;\n"),
 ("    reg [2:0] wki_q, source_q;\n", "    wire [2:0] wki_q=wki;                      // crossing input (opposite stop)\n    reg [2:0] source_q;\n"),
 ("    reg ack_q;\n", "    wire ack_q=ack_i;                          // crossing input (opposite stop)\n"),
 ("in_q<='0;pi_q<='0;eg_q<='0;ri_q<='0;wki_q<='0;", "in_q<='0;eg_q<='0;"),
 ("me<=0;dr<=0;ack_q<=0;", "me<=0;dr<=0;"),
 ("l_out<='0;xq<='0;rce<='0;cco<='0;ack_o<=0;wko<='0;", "l_out<='0;xq<='0;"),
 ("in_q<=l_in;pi_q<=pi;eg_q<=eg;ri_q<=ri;wki_q<=wki;", "in_q<=l_in;eg_q<=eg;"),
 ("dr<=dir;ack_q<=ack_i;", "dr<=dir;"),
 ("xq<='0;rce<='0;cco<='0;ack_o<=0;", "xq<='0;"),
 ("                    rce<={1'b1,in_q[2216:2215],in_q[2214:2211],in_q[2210:2209],in_q[2208],bank,lane[274:264],lane[7:0],lane[263:8]};\n", ""),
 ("                2: cco<={1'b1,in_q[2214:2211],in_q[2210:2209],in_q[2208],in_q[263:8]};\n                3: ack_o<=1;\n", "                default: ;\n"),
 ("            wko<=0;\n", ""),
 ("                if((xq_done & commit_mask[COMMIT_DELAY-1]) != commit_mask[COMMIT_DELAY-1]) fault<=1;\n                else wko<={1'b1,commit_src[COMMIT_DELAY-1]};\n",
  "                if((xq_done & commit_mask[COMMIT_DELAY-1]) != commit_mask[COMMIT_DELAY-1]) fault<=1;\n"),
 ("    // Only valid state resets. All outputs are registered face pins.\n",
  """    // Crossing outputs (replay rce, hub cco, opposite stop wko / ack_o): the next value of the cut output register.
    always @* begin
        rce='0; cco='0; ack_o=1'b0; wko='0;
        if(own) case(kind)
            0: rce={1'b1,in_q[2216:2215],in_q[2214:2211],in_q[2210:2209],in_q[2208],bank,lane[274:264],lane[7:0],lane[263:8]};
            2: cco={1'b1,in_q[2214:2211],in_q[2210:2209],in_q[2208],in_q[263:8]};
            3: ack_o=1'b1;
            default: ;
        endcase
        if(commit_v[COMMIT_DELAY-1] && (xq_done & commit_mask[COMMIT_DELAY-1]) == commit_mask[COMMIT_DELAY-1])
            wko={1'b1,commit_src[COMMIT_DELAY-1]};
    end
    // Only valid state resets. Die-facing outputs are registered face pins.
"""),
])
out.append(t.replace("`timescale 1ns/1ps\n", "").replace("`default_nettype wire\n", ""))
# ---------------------------------------------------------------- hub
t = (S / "ot_vms_hub_static.sv").read_text()
t = ed(t, [
 ("module ot_vms_hub_static #(", "module ot_vms_hub_static_pc #(\n    parameter integer DMUT=0,"),
 ("    assign cwi={cw_valid,cw_payload};\n    assign cci={ccw_valid,ccw_payload};\n",
  "    assign cwi=cw_next;                        // crossing outputs (ring stops): next value of the cut regs\n    assign cci=ccw_next;\n"),
 ("    reg [263:0] rr0,rr1;\n", "    reg [263:0] rr0_r,rr1_r;\n    wire [263:0] rr0=(DMUT==3)?rr0_r:cco0, rr1=(DMUT==3)?rr1_r:cco1;   // crossing inputs (ring stops)\n"),
 ("rr0<=cco0; rr1<=cco1;", "rr0_r<=cco0; rr1_r<=cco1;"),
 ("    reg rvalid0,rvalid1;\n", "    reg rv0_r,rv1_r;\n    wire rvalid0=(DMUT==3)?rv0_r:cco0[263], rvalid1=(DMUT==3)?rv1_r:cco1[263];\n"),
 ("qvalid<='0; bvalid<='0; rvalid0<=0; rvalid1<=0;", "qvalid<='0; bvalid<='0; rv0_r<=0; rv1_r<=0;"),
 ("rvalid0<=cco0[263]; rvalid1<=cco1[263];", "rv0_r<=cco0[263]; rv1_r<=cco1[263];"),
 # HBM-FORM-SPLIT-10+REFORM-B13 (gnw_hub CTS setup -1189.86: arrivals summed by 10 serial conditional +1 -> fault -> status):
 # one hit bit per response source and (c,k); arrivals = balanced popcount mod 8 (same function, same registers, 0 cycles).
 # DMUT 5 (bench mutant): source 9 is not counted.
 ("    reg [2:0] arrivals[0:N-1][0:3];\n", """    reg [2:0] arrivals[0:N-1][0:3];
    reg [9:0] hit[0:N-1][0:3];   // B13: one bit per response source (8 banks + 2 ring stops)
    function automatic [2:0] pc10(input [9:0] h);   // balanced popcount mod 8 (was a serial +1 chain)
        reg [1:0] s0,s1,s2,s3,s4;
        reg [2:0] t0,t1;
        reg [3:0] u;
        begin
            s0={1'b0,h[0]}+{1'b0,h[1]}; s1={1'b0,h[2]}+{1'b0,h[3]}; s2={1'b0,h[4]}+{1'b0,h[5]};
            s3={1'b0,h[6]}+{1'b0,h[7]}; s4={1'b0,h[8]}+{1'b0,h[9]};
            t0={1'b0,s0}+{1'b0,s1}; t1={1'b0,s2}+{1'b0,s3};
            u={1'b0,t0}+{1'b0,t1}+{2'b0,s4};
            pc10=u[2:0];
        end
    endfunction
"""),
 ("begin arrivals[c][k]=0; returned_data[c][k]=0; end", "begin arrivals[c][k]=0; hit[c][k]=0; returned_data[c][k]=0; end"),
 ("                    arrivals[rc][rs]=arrivals[rc][rs]+3'd1;\n", "                    hit[rc][rs][b]=!(DMUT==5 && b==9);\n"),
 ("        for(c=0;c<N;c=c+1) begin\n            for(k=0;k<4;k=k+1) if(arrivals[c][k]!=0)\n",
  "        for(c=0;c<N;c=c+1) for(k=0;k<4;k=k+1) arrivals[c][k]=pc10(hit[c][k]);\n        for(c=0;c<N;c=c+1) begin\n            for(k=0;k<4;k=k+1) if(arrivals[c][k]!=0)\n"),
])
out.append(t.replace("`timescale 1ns/1ps\n", "").replace("`default_nettype wire\n", "").replace("`default_nettype none\n", ""))
# ---------------------------------------------------------------- replay
t = (S / "ot_vms_rcl_static.sv").read_text()
t = ed(t, [
 ("module ot_vms_rcl_static #(parameter integer MUT=0) (", "module ot_vms_rcl_static_pc #(parameter integer MUT=0, parameter integer DMUT=0) ("),
 ("    reg [287:0] a,b;\n", "    wire [287:0] a=rce0, b=rce1;               // crossing inputs (ring stops)\n"),
 ("            a<=0;b<=0;response<=0;me<=0;select_q<=0;enable_q<=0;\n            hq<=0;ri0<=0;ri1<=0;fault<=0;",
  "            response<=0;me<=0;select_q<=0;enable_q<=0;\n            hq<=0;fault<=0;"),
 ("            a<=rce0;b<=rce1;response<=", "            response<="),
 ("            ri0<={response[273] && !return_port,response[265:264],response[263:260],response[259:258],response[256],response[255:0]};\n            ri1<={response[273] && return_port,response[265:264],response[263:260],response[259:258],response[256],response[255:0]};\n", ""),
 ("    always @(posedge clk or negedge rst_n)\n", """    // Crossing outputs (ring stops): next value of the cut ri registers (response resets, so ri is 0 in reset).
    wire rp=return_port ^ (DMUT==4);
    always @* begin
        ri0={response[273] && !rp,response[265:264],response[263:260],response[259:258],response[256],response[255:0]};
        ri1={response[273] && rp,response[265:264],response[263:260],response[259:258],response[256],response[255:0]};
    end
    always @(posedge clk or negedge rst_n)
"""),
])
out.append(t.replace("`timescale 1ns/1ps\n", "").replace("`default_nettype wire\n", "").replace("`default_nettype none\n", ""))
# ---------------------------------------------------------------- status
t = (S / "ot_vms_status_static.sv").read_text()
t = ed(t, [
 ("module ot_vms_status_static (", "module ot_vms_status_static_pc #(parameter integer DMUT=0) ("),
 ("    input wire ring_fault,\n", "    input wire ring_fault,       // same-piece fault (replay), flags stage as before\n    input wire ring_fault_late,  // ring stop faults over a crossing: 2 face edges late = the flags1 stage\n"),
 ("        flags={hub_status[2]|hub_status[0]|ring_fault,hub_status[1],1'b0};",
  "        flags={hub_status[2]|hub_status[0]|ring_fault|(DMUT==2 && ring_fault_late),hub_status[1],1'b0};"),
 ("vmstat<=sum_valid[1]?{flags1,", "vmstat<=sum_valid[1]?{flags1|{DMUT!=2 && ring_fault_late,2'b0},"),
])
out.append(t.replace("`timescale 1ns/1ps\n", "").replace("`default_nettype wire\n", "").replace("`default_nettype none\n", ""))
s = "".join(out).rstrip() + "\n`default_nettype wire\n"
s = "`timescale 1ns/1ps\n" + s
Path(sys.argv[2]).write_text(s)
print("wrote", sys.argv[2], len(s.splitlines()), "lines")
